globalThis.KENGURU_LEGACY = [[2005,"3–4 классы",[[824,99,"В этом году ежегодный конкурс «Кенгуру» проводится в России уже в 12-й раз. В каком году был первый конкурс?",{},"B","Первый конкурс",[["Посчитай промежутки","От первого конкурса до двенадцатого проходит 11 лет. Первый конкурс уже входит в число двенадцати."],["Отсчитай годы назад","Вычти 11 из 2005. Первый конкурс прошёл в 1994 году."]],""],[824,97,"Общий вес троих детей 72 кг. Маша весит столько же, сколько два ее младших брата вместе. Сколько весит Маша?",{"0":[51.7,65.9,31.3,23.5],"1":[208.4,65.9,31.3,23.5],"2":[355,65.9,32.6,23.5],"3":[501.4,65.9,32.6,23.5],"4":[648.1,65.9,31.3,23.5]},"D","Вес Маши",[["Раздели общий вес","Троих детей можно разделить на две группы одинакового веса. В одной Маша, в другой — два брата."],["Найди вес одной группы","Маша весит половину общего веса, то есть 72 : 2 = 36 кг."]],""],[824,273,"Каждый из восьми кенгуру может перепрыгнуть на любую клетку квадратной таблицы 4×4. Им надо расположиться так, чтобы в каждой строчке и каждом столбце этой таблицы оказалось ровно по 2 кенгуру. Наименьшее число кенгуру, которым придется для этого прыгнуть, равно",{"0":[51.7,210.2,31.3,23.5],"1":[211.6,210.2,31.3,23.5],"2":[371.5,210.2,32.6,23.5],"3":[51.7,241.9,32.6,23.5],"4":[211.6,241.9,31.3,23.5]},"D","Прыжок одного кенгуру",[["Найди избыток и нехватку","Во второй строке три кенгуру, а в четвёртой — один. В третьем столбце три кенгуру, а во втором — один."],["Сделай один прыжок","Кенгуру из второй строки третьего столбца прыгает в четвёртую строку второго столбца. Теперь в каждой строке и каждом столбце по два. Без прыжка условие не выполнялось."]],""],[824,188,"В магазин привезли 4 одинаковые полные коробки: в одной – апельсины, в другой – яблоки, в третьей – мандарины, в четвертой – вишни. В какой коробке наибольшее число плодов?",{"0":[51.7,92.8,31.3,23.5],"1":[51.7,124.6,31.3,23.5],"2":[51.7,156.3,32.6,23.5],"3":[444.9,92.8,32.6,23.5],"4":[444.9,124.6,31.3,23.5]},"D","Четыре коробки",[["Сравни размеры плодов","Коробки одинаковые по размеру и заполнены. Из перечисленных плодов вишни самые мелкие."],["Выбери коробку","Мелкие плоды занимают меньше места по одному. Поэтому больше всего плодов в коробке с вишнями."]],""],[824,144,"Бабочка села на записанное в тетради верное равенство. Какое число она закрыла?",{"0":[51.7,112,31.3,23.5],"1":[208.4,112,31.3,23.5],"2":[354.9,112,32.6,23.5],"3":[501.4,112,32.6,23.5],"4":[648,112,31.3,23.5]},"C","Число под бабочкой",[["Вычисли левую часть","На рисунке слева записано 2005 − 205. Это 1800."],["Восстанови второе слагаемое","Справа к 1300 прибавили скрытое число и тоже получили 1800. Под бабочкой 1800 − 1300 = 500."]],""],[824,126,"Какое из чисел обладает такими свойствами: оно четное, все его цифры различны, а число сотен в два раза больше числа единиц?",{"0":[51.7,95.2,31.3,23.5],"1":[208.4,95.2,31.3,23.5],"2":[355,95.2,32.6,23.5],"3":[501.4,95.2,32.6,23.5],"4":[648.1,95.2,31.3,23.5]},"E","Число с тремя условиями",[["Проверь чётность и цифры","Число 4683 нечётное. В числе 4874 повторяется цифра 4. Для следующей проверки остаются 1236, 3478 и 8462."],["Сравни сотни и единицы","В 1236 цифра сотен 2, а цифра единиц 6. В 3478 это 4 и 8. В обоих случаях сотен меньше. Лишь у 8462 цифра сотен 4 вдвое больше цифры единиц 2."]],""],[845,229,"Квадрат разрезали на 3 кусочка. Два из них изображены на рисунке справа. Укажите третий кусочек.",{"0":[84.4,197.1,31.4,23.5],"1":[221.4,197.1,31.4,23.5],"2":[344.9,197.1,32.6,23.5],"3":[514.4,197.1,32.6,23.5],"4":[680.6,197.1,31.4,23.5]},"B","Третий кусочек квадрата",[["Соедини скошенные края","Сдвинь правую деталь вниз и влево, чтобы её наклонная сторона прилегла к наклонной стороне левой детали."],["Посмотри на пустой угол","Правая деталь образует нижний край большого квадрата. Для завершения верхнего правого угла не хватает маленького квадрата B."]],""],[845,127,"В летнем лагере «Кенгуру» Алеша решал по 4 задачи в день, а Андрей – по 2 задачи. Алеша решил все задачи за 5 дней. За сколько дней решил эти же задачи Андрей?",{"0":[51.7,95.2,31.3,23.5],"1":[208.3,95.2,31.3,23.5],"2":[354.9,95.2,32.6,23.5],"3":[501.4,95.2,32.6,23.5],"4":[647.9,95.2,31.3,23.5]},"E","Задачи в лагере",[["Найди общее число задач","Алёша решал по четыре задачи пять дней. Это 4 × 5 = 20 задач."],["Раздели по дням Андрея","Андрей решал по две задачи в день. Ему понадобилось 20 : 2 = 10 дней."]],""],[845,127,"Никита живет в своем доме вместе с папой, мамой и братом. А еще с ними живут собака, две кошки, два попугая и четыре золотые рыбки. Сколько всего ног у обитателей этого дома?",{"0":[51.7,95.2,31.3,23.5],"1":[208.4,95.2,31.3,23.5],"2":[355,95.2,32.6,23.5],"3":[501.4,95.2,32.6,23.5],"4":[648,95.2,31.3,23.5]},"B","Ноги обитателей дома",[["Посчитай людей и четвероногих","У четверых людей 4 × 2 = 8 ног. У собаки и двух кошек 3 × 4 = 12 лап."],["Добавь птиц","У двух попугаев ещё 2 × 2 = 4 ноги. У рыбок ног нет. Всего 8 + 12 + 4 = 24."]],""],[845,163,"Если одно из чисел увеличить в 20 раз, а другое уменьшить в 10 раз, то произведение этих чисел",{"0":[51.7,68.2,31.4,23.5],"1":[51.7,99.9,31.4,23.5],"2":[51.7,131.6,32.7,23.5],"3":[419.7,68.2,32,23.5],"4":[420.6,99.9,31,23.5]},"A","Что стало с произведением",[["Проследи за двумя действиями","Увеличение одного множителя в 20 раз увеличивает произведение в 20 раз. Уменьшение другого в 10 раз делит результат на 10."],["Объедини изменения","Умножить на 20 и разделить на 10 — то же самое, что умножить на 2. Произведение удвоится."]],""],[845,151,"На столе лежала коробка с конфетами. Саша взял оттуда половину конфет, потом половину оставшихся конфет взял Коля. Затем Света взяла из коробки половину того, что там было. После этого осталось 3 конфеты. Сколько конфет было в коробке сначала?",{"0":[51.7,119.8,31.3,23.5],"1":[208.3,119.8,31.3,23.5],"2":[354.9,119.8,32.6,23.5],"3":[501.4,119.8,32.6,23.5],"4":[648,119.8,31.3,23.5]},"D","Конфеты в коробке",[["Верни конфеты Светы и Коли","После Светы осталось три конфеты, то есть половина того, что было перед её ходом. До Светы было 6, а до Коли — вдвое больше, 12."],["Верни конфеты Саши","После Саши осталось 12 конфет, значит, до его хода в коробке было 12 × 2 = 24."]],""],[845,267,"За один ход Петер поворачивает квадрат с закрашенным треугольником вокруг точки P, как показано на рисунке. В каком положении будет треугольник после 17 ходов?",{"0":[78.4,236.3,31.4,23.5],"1":[225,236.3,31.4,23.5],"2":[371.6,236.3,32.7,23.5],"3":[518.1,236.3,32.7,23.5],"4":[664.7,236.3,31.4,23.5]},"A","Семнадцать поворотов",[["Найди полный круг","За первый ход треугольник перемещается сверху вправо, а за второй — вниз. Каждый ход поворачивает квадрат на четверть оборота. После четырёх ходов он вернётся в начальное положение."],["Оставь лишний ход","В 17 ходах четыре полных оборота и один ход. Треугольник окажется справа, как на рисунке A."]],""],[824,123,"У Даши было 9 кусочков бумаги. Некоторые из них она разрезала на три части. Всего получилось 15 кусочков. Сколько кусочков разрезала Даша?",{"0":[51.7,92.8,31.3,23.5],"1":[208.3,92.8,31.3,23.5],"2":[354.9,92.8,32.6,23.5],"3":[501.3,92.8,32.6,23.5],"4":[647.9,92.8,31.3,23.5]},"C","Разрезанные кусочки",[["Посчитай прибавку от разрезания","Когда один кусочек разрезают на три, вместо одного получаются три. Общее число увеличивается на два."],["Раздели общую прибавку","Было 9 кусочков, стало 15. Прибавилось 15 − 9 = 6, значит, разрезали 6 : 2 = 3 кусочка."]],""],[824,181,"Пять карточек с цифрами лежат на столе в таком порядке: 5, 1, 4, 3, 2. За один ход разрешается поменять местами любые две карточки. За какое наименьшее число ходов можно расположить их в порядке 1, 2, 3, 4, 5?",{"0":[51.7,149.2,31.3,23.5],"1":[161.7,149.2,31.3,23.5],"2":[271.6,149.2,32.6,23.5],"3":[381.5,149.2,32.6,23.5],"4":[491.3,149.2,31.3,23.5]},"B","Карточки по порядку",[["Получится ли за два хода","Сначала все пять карточек лежат на чужих местах. За один обмен можно поставить на места не более двух карточек. За два обмена нельзя исправить все пять."],["Выполни три обмена","Поменяй карточки 5 и 1, затем 5 и 2, затем 4 и 3. Получится 1, 2, 3, 4, 5. Значит, минимум — три хода."]],""],[824,167,"Царь Кащей подобрел и решил потратить 50 золотых монет на подарки детям. В сундуке у него хранится 5 ларцов, в каждом ларце по 3 шкатулки, а в каждой шкатулке по 10 золотых монет. Сундук, ларцы и шкатулки заперты на замки. Какое наименьшее число замков потребуется открыть Кащею, чтобы достать 50 монет?",{"0":[51.7,135.6,31.3,23.5],"1":[211.6,135.6,31.3,23.5],"2":[358.1,135.6,32.6,23.5],"3":[504.7,135.6,32.6,23.5],"4":[651.2,135.6,31.3,23.5]},"D","Замки Кащея",[["Посчитай шкатулки и ларцы","Для 50 монет нужно открыть 50 : 10 = 5 шкатулок. В одном ларце их только три, поэтому надо открыть хотя бы два ларца."],["Прибавь замок сундука","Можно взять три шкатулки из одного ларца и две из другого. Вместе с сундуком получаем 5 + 2 + 1 = 8 замков."]],""],[824,154,"Из 6 спичек можно сложить только один прямоугольник (он изображен на рисунке). Сколько различных прямоугольников можно сложить, используя каждый раз 14 спичек?",{"0":[51.7,122.2,31.3,23.5],"1":[208.3,122.2,31.3,23.5],"2":[354.9,122.2,32.6,23.5],"3":[501.3,122.2,32.6,23.5],"4":[647.9,122.2,31.3,23.5]},"C","Прямоугольники из спичек",[["Найди сумму соседних сторон","На противоположных сторонах число спичек одинаково. На две соседние стороны приходится 14 : 2 = 7 спичек."],["Перебери размеры","Пары длин равны 1 и 6, 2 и 5, 3 и 4. Переставить длины — значит повернуть тот же прямоугольник. Всего три варианта."]],""],[824,290,"Во дворе живут два кота и две собаки. Кот Малыш боится обеих собак, а кот Тоша боится Шарика и дружит с Бобиком. Какое из утверждений неверно?",{"0":[51.7,95.2,31.3,23.5],"1":[51.7,129.3,31.3,23.5],"2":[51.7,163.3,32.6,23.5],"3":[51.7,197.4,32.6,23.5],"4":[51.7,231.5,31.4,23.5]},"D","Коты и собаки",[["Сравни, кого боятся коты","Оба кота боятся Шарика. Малыш боится и Бобика, а Тоша с Бобиком дружит."],["Проверь утверждение D","Шарика боятся двое, Бобика — один. Значит, обеих собак кто-то боится. Утверждение D неверно."]],""],[824,278,"у какого-то из котов. 18. Какой из кубиков можно склеить из заготовки, изображенной справа?",{"0":[71.7,253.6,31.4,23.5],"1":[178.4,253.6,31.4,23.5],"2":[285,253.6,32.7,23.5],"3":[391.6,253.6,32.7,23.5],"4":[498.1,253.6,31.4,23.5]},"E","Кубик из заготовки",[["Сложи шестую грань","Полностью серая клетка станет одной гранью, четыре соседние белые клетки — стенками. Четыре маленьких квадрата сомкнутся напротив серой грани."],["Сравни видимые грани","На составной грани серые четвертинки лежат по диагонали. У куба видна хотя бы одна из двух противоположных окрашенных граней, а вместе их увидеть нельзя. Этим условиям отвечает E."]],""],[845,131,"Две девочки и три мальчика вместе съели 16 порций мороженого. Каждый мальчик съел в 2 раза больше порций, чем каждая девочка. Сколько порций съедят 3 девочки и 2 мальчика с такими же аппетитами?",{"0":[51.7,100.2,31.3,23.5],"1":[208.4,100.2,31.3,23.5],"2":[354.9,100.2,32.6,23.5],"3":[501.4,100.2,32.6,23.5],"4":[648,100.2,31.3,23.5]},"C","Порции мороженого",[["Вырази порции через одну девочку","Каждый мальчик съедает столько же, сколько две девочки. Значит, две девочки и три мальчика съедают столько же, сколько восемь девочек. На каждую девочку приходится 16 : 8 = 2 порции, на мальчика — 4."],["Сложи порции новой группы","Три девочки и два мальчика съедят 3 × 2 + 2 × 4 = 14 порций."]],""],[845,164,"Вокруг прямоугольного сквера проложена дорожка, которая на всем своем протяжении имеет одинаковую ширину. Наружная граница дорожки на 8 м длиннее внутренней. Чему равна ширина дорожки?",{"0":[51.7,133.2,31.4,23.5],"1":[171.7,133.2,31.4,23.5],"2":[271.6,133.2,32.6,23.5],"3":[364.8,133.2,32.6,23.5],"4":[464.9,133.2,31.4,23.5]},"B","Ширина дорожки",[["Сравни стороны прямоугольников","Каждая сторона внешнего прямоугольника длиннее соответствующей внутренней на две ширины дорожки, по одной с каждого конца."],["Сравни периметры","У четырёх сторон разница в сумме составляет восемь ширин. Это 8 м, поэтому ширина равна 8 : 8 = 1 м."]],""],[845,110,"У каждого двузначного числа нашли произведение цифр, потом у каждого такого произведения подсчитали сумму цифр. Какая сумма самая большая?",{"0":[51.7,78.7,31.3,23.5],"1":[165,78.7,31.3,23.5],"2":[278.2,78.7,32.6,23.5],"3":[391.5,78.7,32.6,23.5],"4":[504.8,78.7,31.3,23.5]},"C","Сумма цифр произведения",[["Найди большую сумму","Можно взять число 77. Произведение его цифр 7 × 7 = 49, а сумма цифр произведения равна 4 + 9 = 13."],["Проверь большие суммы","Произведение не больше 9 × 9 = 81. До 81 сумму цифр больше 13 имеют только 59, 68, 69, 77, 78 и 79."],["Проверь множители","59 и 79 — простые. В остальных числах есть множитель больше 9: 68 = 4 × 17, 69 = 3 × 23, 77 = 7 × 11, 78 = 6 × 13. Ни одно не получается из двух цифр. Наибольшая сумма — 13."]],""],[845,162,"",{},"B","Треугольники и квадраты",[["Посчитай треугольники по размеру","У каждого треугольника наклонная сторона лежит на большой наклонной стороне рисунка. Треугольников с катетом в одну клетку 5, с катетом в две — 4, далее 3, 2 и 1. Итого 15."],["Посчитай квадраты","Квадратов в одну клетку по рядам 4, 3, 2 и 1, всего 10. Квадратов со стороной в две клетки 3. Более крупный квадрат не помещается."],["Сравни результаты","Треугольников на 15 − 13 = 2 больше."]],""],[845,115,"В семье четверо детей, им 5, 8, 13 и 15 лет, а зовут их Таня, Юра, Света и Лена. Одна девочка ходит в детский сад, Таня старше Юры, а сумма лет Тани и Светы делится на три. Сколько лет Лене?",{"0":[51.7,84.6,31.3,23.5],"1":[151.7,84.6,31.3,23.5],"2":[242.1,84.6,32.6,23.5],"3":[351.6,84.6,32.6,23.5],"4":[451.4,84.6,31.3,23.5]},"D","Возраст детей",[["Выбери пару с подходящей суммой","Из данных возрастов только пары 5 и 13, а также 8 и 13 дают сумму, кратную трём. Это возможные возрасты Тани и Светы."],["Учти, кто ходит в детский сад","Пятилетний ребёнок — девочка. Если бы Тане и Свете было 8 и 13, Юре пришлось бы быть пятилетним, иначе он был бы старше Тани."],["Определи возраст Лены","Значит, Свете 5, Тане 13, Юре 8. Лене остаётся 15 лет."]],""],[845,164,"Австралийский ленивец Бумми почти всю жизнь проводит на дереве. Однако, если месяц начинается и кончается одним и тем же днем недели, то он слезает с дерева и отправляется путешествовать на весь этот месяц. Сколько месяцев с начала 2005 года по конец 2015 года Бумми проведет в путешествиях?",{"0":[51.7,133.2,31.3,23.5],"1":[208.3,133.2,31.3,23.5],"2":[354.9,133.2,32.6,23.5],"3":[501.4,133.2,32.6,23.5],"4":[648,133.2,31.3,23.5]},"B","Путешествия Бумми",[["Найди длину месяца","От первого до последнего числа месяца проходит на один день меньше, чем дней в месяце. Чтобы дни недели совпали, это число должно делиться на 7. Для месяцев длиной 28, 29, 30 или 31 день подходит только 29."],["Посчитай високосные февралѝ","С 2005 по 2015 год 29 дней было только в феврале 2008 и в феврале 2012 года. Значит, Бумми путешествовал два месяца."]],""],[845,140,"На белой доске 5×5 Петя закрасил какие-то клетки синим цветом, а какие-то – красным (каждым цветом закрашена хотя бы одна клетка). Никакие две клетки красного и синего цвета не имеют общей стороны. Какое наибольшее число клеток могло быть закрашено?",{"0":[51.7,109,31.3,23.5],"1":[208.4,109,31.3,23.5],"2":[355,109,32.6,23.5],"3":[501.5,109,32.6,23.5],"4":[648.1,109,31.3,23.5]},"B","Закраска доски",[["Докажи, что нужна хотя бы пара белых клеток","Если оставить белой лишь одну клетку, в каждой из остальных строк и столбцов можно свободно пройти по закрашенным клеткам. Даже из строки с белой клеткой можно выйти по целому столбцу. Значит, любую закрашенную клетку можно соединить с любой другой по общим сторонам."],["Сохрани два цвета","На пути от красной к синей клетке где-то встретились бы соседи разных цветов. Поэтому одной белой клетки мало. Оставь белыми две клетки, соседние с угловой. Угол закрась красным, остальные — синим. Получится 25 − 2 = 23 закрашенные клетки."]],""],[845,142,"В числовом ребусе различные значки обозначают различные цифры, а одинаковые значки – одинаковые цифры. Какую наименьшую цифру может обозначать?",{"0":[45.1,111.4,31.3,23.5],"1":[171.7,111.4,31.3,23.5],"2":[291.5,111.4,32.6,23.5],"3":[411.5,111.4,32.6,23.5],"4":[531.4,111.4,31.3,23.5]},"B","Треугольник в ребусе",[["Сравни десятки и сотни","До учёта переносов в десятках и в сотнях складываются одни и те же три цифры. В сотнях вместе с переносом должно выйти 20. Перенос из десятков не больше 2, поэтому сумма трёх цифр без переноса не меньше 18."],["Вычисли сумму единиц","В десятках сумма с переносом оканчивается нулём. Она не меньше 18 и не больше 9 + 8 + 7 + 2 = 26, поэтому равна 20. В сотни переносят 2, сумма трёх разных цифр равна 18. Из единиц тоже перенесли 2, ведь в десятках с переносом получилось 20."],["Найди наименьший треугольник","В единицах квадрат и два треугольника дают 25. Если треугольник равен 7 или меньше, квадрат пришлось бы сделать не меньше 11. При треугольнике 8 квадрат равен 9, сердце — 1. Проверка: 999 + 118 + 888 = 2005."]],""]]]];
globalThis.KENGURU_LEGACY_CONDITIONS = {"2005":{"1":{"question":"В этом году ежегодный конкурс «Кенгуру» проводится в России уже в 12-й раз. В каком году был первый конкурс?","choices":["1993","1994","1995","1894","994"]},"2":{"question":"Общий вес троих детей 72 кг. Маша весит столько же, сколько два ее младших брата вместе. Сколько весит Маша?","choices":["18 кг","24 кг","32 кг","36 кг","52 кг"]},"4":{"question":"В магазин привезли 4 одинаковые полные коробки: в одной – апельсины, в другой – яблоки, в третьей – мандарины, в четвертой – вишни. В какой коробке наибольшее число плодов?","image":"assets/legacy-conditions/2005/task-04.webp","imageWidth":903,"imageHeight":124},"5":{"question":"Бабочка села на число в правой части верного равенства 2005 − 205 = 1300 + □. Какое число она закрыла?","choices":["250","400","500","705","1800"]},"6":{"question":"Какое из чисел обладает такими свойствами: оно четное, все его цифры различны, а число сотен в два раза больше числа единиц?","choices":["1236","3478","4683","4874","8462"]},"7":{"question":"Квадрат разрезали на 3 кусочка. Два из них изображены на рисунке справа. Укажите третий кусочек.","image":"assets/legacy-conditions/2005/task-07.webp","imageWidth":957,"imageHeight":290},"8":{"question":"В летнем лагере «Кенгуру» Алеша решал по 4 задачи в день, а Андрей – по 2 задачи. Алеша решил все задачи за 5 дней. За сколько дней решил эти же задачи Андрей?","choices":["4","5","6","8","10"]},"9":{"question":"Никита живет в своем доме вместе с папой, мамой и братом. А еще с ними живут собака, две кошки, два попугая и четыре золотые рыбки. Сколько всего ног у обитателей этого дома?","choices":["22","24","28","32","40"]},"10":{"question":"Если одно из чисел увеличить в 20 раз, а другое уменьшить в 10 раз, то произведение этих чисел","choices":["увеличится в 2 раза","уменьшится в 2 раза","увеличится в 20 раз","уменьшится в 20 раз","не изменится"]},"11":{"question":"На столе лежала коробка с конфетами. Саша взял оттуда половину конфет, потом половину оставшихся конфет взял Коля. Затем Света взяла из коробки половину того, что там было. После этого осталось 3 конфеты. Сколько конфет было в коробке сначала?","choices":["6","12","18","24","36"]},"12":{"question":"За один ход Петер поворачивает квадрат с закрашенным треугольником вокруг точки P, как показано на рисунке. В каком положении будет треугольник после 17 ходов?","image":"assets/legacy-conditions/2005/task-12.webp","imageWidth":944,"imageHeight":330},"13":{"question":"У Даши было 9 кусочков бумаги. Некоторые из них она разрезала на три части. Всего получилось 15 кусочков. Сколько кусочков разрезала Даша?","choices":["1","2","3","4","5"]},"14":{"question":"Пять карточек с цифрами лежат на столе в таком порядке: 5, 1, 4, 3, 2. За один ход разрешается поменять местами любые две карточки. За какое наименьшее число ходов можно расположить их в порядке 1, 2, 3, 4, 5?","choices":["2","3","4","5","6"],"image":"assets/legacy-conditions/2005/task-14.webp","imageWidth":254,"imageHeight":170},"15":{"question":"Царь Кащей подобрел и решил потратить 50 золотых монет на подарки детям. В сундуке у него хранится 5 ларцов, в каждом ларце по 3 шкатулки, а в каждой шкатулке по 10 золотых монет. Сундук, ларцы и шкатулки заперты на замки. Какое наименьшее число замков потребуется открыть Кащею, чтобы достать 50 монет?","choices":["5","6","7","8","9"]},"16":{"question":"Из 6 спичек можно сложить только один прямоугольник (он изображен на рисунке). Сколько различных прямоугольников можно сложить, используя каждый раз 14 спичек?","choices":["1","2","3","4","6"],"image":"assets/legacy-conditions/2005/task-16.webp","imageWidth":247,"imageHeight":122},"17":{"question":"Во дворе живут два кота и две собаки. Кот Малыш боится обеих собак, а кот Тоша боится Шарика и дружит с Бобиком. Какое из утверждений неверно?","choices":["Каждый из котов боится какой-то из собак.","Есть кот, который не боится какой-то из собак.","Есть собака, которую боятся оба кота.","Есть собака, которую не боится ни один из котов.","Каждая из двух собак вызывает страх у какого-то из котов."]},"18":{"question":"Какой из кубиков можно склеить из заготовки, изображенной справа?","image":"assets/legacy-conditions/2005/manual-18.webp","imageWidth":518,"imageHeight":360},"19":{"question":"Две девочки и три мальчика вместе съели 16 порций мороженого. Каждый мальчик съел в 2 раза больше порций, чем каждая девочка. Сколько порций съедят 3 девочки и 2 мальчика с такими же аппетитами?","choices":["12","13","14","16","17"]},"20":{"question":"Вокруг прямоугольного сквера проложена дорожка, которая на всем своем протяжении имеет одинаковую ширину. Наружная граница дорожки на 8 м длиннее внутренней. Чему равна ширина дорожки?","choices":["50 cм","1 м","2 м","3 м","4 м"],"image":"assets/legacy-conditions/2005/task-20.webp","imageWidth":284,"imageHeight":171},"21":{"question":"У каждого двузначного числа нашли произведение цифр, потом у каждого такого произведения подсчитали сумму цифр. Какая сумма самая большая?","choices":["9","11","13","15","18"]},"22":{"question":"На этой картинке можно увидеть треугольники и квадраты, причем квадратов меньше, чем треугольников. На сколько?","choices":["1","2","3","4","5"],"image":"assets/legacy-conditions/2005/task-22.svg","imageWidth":220,"imageHeight":217},"23":{"question":"В семье четверо детей, им 5, 8, 13 и 15 лет, а зовут их Таня, Юра, Света и Лена. Одна девочка ходит в детский сад, Таня старше Юры, а сумма лет Тани и Светы делится на три. Сколько лет Лене?","choices":["5","8","13","15","невозможно определить"]},"24":{"question":"Австралийский ленивец Бумми почти всю жизнь проводит на дереве. Однако, если месяц начинается и кончается одним и тем же днем недели, то он слезает с дерева и отправляется путешествовать на весь этот месяц. Сколько месяцев с начала 2005 года по конец 2015 года Бумми проведет в путешествиях?","choices":["1","2","4","12","24"]},"25":{"question":"На белой доске 5×5 Петя закрасил какие-то клетки синим цветом, а какие-то – красным (каждым цветом закрашена хотя бы одна клетка). Никакие две клетки красного и синего цвета не имеют общей стороны. Какое наибольшее число клеток могло быть закрашено?","choices":["25","23","22","21","20"]},"26":{"question":"В числовом ребусе различные значки обозначают различные цифры, а одинаковые значки — одинаковые цифры. Какую наименьшую цифру может обозначать △?","choices":["9","8","6","4","2"],"image":"assets/legacy-conditions/2005/manual-26.webp","imageWidth":139,"imageHeight":127}}};
'use strict';

(() => {
  const latin = ['A', 'B', 'C', 'D', 'E'];
  const cyrillic = ['А', 'Б', 'В', 'Г', 'Д'];
  const escape = value => String(value).replaceAll('&', '&amp;').replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;').replaceAll('"', '&quot;');
  const archive = globalThis.KENGURU_ARCHIVE ??= {};
  const source = 'https://ipokengu.ru/public/task';
  const ink = '#173439';
  const teal = '#237e79';
  const mint = '#e5f2ea';
  const muted = '#e8eee8';
  const line = '#b3c6bf';
  const gold = '#f7dda8';

  const text = (x, y, value, size = 27, color = ink, anchor = 'middle') =>
    `<text x="${x}" y="${y}" fill="${color}" font-family="system-ui, sans-serif" font-weight="700" font-size="${size}" text-anchor="${anchor}" dominant-baseline="middle">${escape(value)}</text>`;
  const box = (x, y, w, h, fill, stroke = 'none', radius = 10) =>
    `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${radius}" fill="${fill}" stroke="${stroke}"/>`;
  const segment = (x1, y1, x2, y2, color, width = 3) =>
    `<path d="M${x1} ${y1} L${x2} ${y2}" fill="none" stroke="${color}" stroke-width="${width}" stroke-linecap="round"/>`;
  const dot = (x, y, radius, fill) => `<circle cx="${x}" cy="${y}" r="${radius}" fill="${fill}"/>`;
  const svg = (width, height, label, inside, className = 'legacy-scene') =>
    `<svg class="${className}" viewBox="0 0 ${width} ${height}" role="img" aria-label="${escape(label)}">${inside}</svg>`;
  const image = (url, width, height) => `<image href="${url}" width="${width}" height="${height}"/>`;
  const progress = (frame, end) => Math.max(0, Math.min(1, frame / end));

  function renderOriginal(url, width, height, label, mark, frame) {
    let focus = '';
    if (mark) {
      const [x, y, w, h] = mark;
      const dash = .68 + .32 * progress(frame, 8);
      focus = `<rect x="${x - 4}" y="${y - 2}" width="${w + 8}" height="${h + 4}" rx="4" fill="none" stroke="${teal}" stroke-width="4" pathLength="1" stroke-dasharray="${dash} 1"/>`;
    }
    return svg(width, height, label, image(url, width, height) + focus);
  }

  function crop(url, width, height, [sx, sy, sw, sh], x, y, w, h) {
    return `<svg x="${x}" y="${y}" width="${w}" height="${h}" viewBox="${sx} ${sy} ${sw} ${sh}" style="overflow:hidden">${image(url, width, height)}</svg>`;
  }

  function workedScene([height, drawing], label, answer) {
    const size = 720;
    const band = answer ? 51 : 0;
    const badge = answer
      ? box(16, height, size - 32, 42, mint, line) + text(size / 2, height + 21, `Ответ ${answer}`, 24, teal)
      : '';
    return svg(size, height + band, label, drawing + badge, 'legacy-scene legacy-worked-scene');
  }

  // Extract only equations that the author explicitly uses in this step. A
  // space can group thousands, so it must not split their numeric tokens.
  const number = String.raw`[−-]?\d+(?:[ \u00a0\u202f]\d{3}(?!\d))*(?:[.,]\d+)?`;
  const operator = String.raw`[+−–×·⋅*÷:/=<>≤≥-]`;
  const equation = new RegExp(String.raw`${number}(?:\s*${operator}\s*${number})+`, 'gu');
  const tokens = new RegExp(String.raw`^(${number})|(${operator})\s*(${number})`, 'gu');

  function equationsIn(message) {
    return [...message.matchAll(equation)].map(match => match[0])
      .filter(value => /[=<>≤≥]/u.test(value))
      .map(value => [...value.matchAll(tokens)].flatMap(([, first, sign, next]) => first ? [first] : [sign, next]));
  }

  function drawEquations(rows, frame) {
    const drawing = rows.map((parts, row) => {
      const current = Math.min(parts.length - 1, Math.floor(Math.max(0, frame - row * 4) / 2));
      const sizes = parts.map((part, i) => i % 2 ? 32 : Math.max(48, 23 + part.length * 17));
      const width = sizes.reduce((sum, w) => sum + w, 0);
      const factor = Math.min(640 / width, 1);
      let x = (720 - width * factor) / 2;
      const y = 15 + row * 75;
      return box(16, y, 688, 62, '#f6f8f3') + parts.map((part, i) => {
        const w = sizes[i] * factor;
        const highlight = current === i;
        const result = i === parts.length - 1;
        const plate = (i % 2 === 0 || highlight)
          ? box(x + 2, y + 7, w - 4, 48, highlight ? gold : result ? mint : '#fff', result ? teal : 'none') : '';
        const item = plate + text(x + w / 2, y + 31, part, 32 * factor, result ? teal : ink);
        x += w;
        return item;
      }).join('');
    }).join('');
    return [rows.length * 75 + 13, drawing];
  }

  // The checked statement and the worksheet choices are transcribed together.
  // For illustrated choices, the approach below uses the original artwork.
  const authored = {
    '2001/3': {
      question: 'У Йозефа было 7 палочек. Он разломал одну из них пополам. Сколько теперь у него палочек?',
      choices: ['5', '6', '7', '8', '9'],
      draw: drawSticks,
    },
    '2002/2': {
      question: 'Чему равно число 2 + 2 − 2 + 2 − 2 + 2 − 2 + 2 − 2 + 2?',
      choices: ['0', '2', '4', '12', '20'],
      draw: drawPairs,
    },
    '2003/3': {
      question: 'На какой картинке сердечки составляют ровно три четверти от общего числа фигурок?',
      crop: [73, 65, 662, 131],
      illustration: 'Пять рисунков с сердечками, ромбами и треугольниками, варианты от A до E',
      draw: drawHearts,
    },
    '2004/4': {
      question: 'Сережа шел по лестнице, шагая через ступеньку (первую ступеньку он пропустил). При этом он считал шаги: «Один, два, три…». После того, как он сказал «пять», оказалось, что осталась одна ступенька. Сколько всего ступенек на лестнице?',
      choices: ['5', '7', '9', '11', '12'],
      draw: drawStairs,
    },
    '2005/3': {
      question: 'Каждый из восьми кенгуру может перепрыгнуть на любую клетку квадратной таблицы 4 × 4. Им надо расположиться так, чтобы в каждой строчке и каждом столбце этой таблицы оказалось ровно по 2 кенгуру. Какое наименьшее число кенгуру должно для этого прыгнуть?',
      choices: ['4', '3', '2', '1', '0'],
      crop: [537, 8, 244, 240],
      illustration: 'Квадратная таблица с восемью кенгуру',
      draw: drawKangaroos,
    },
    '2006/10': {
      question: 'Петя прибавляет различные однозначные числа к числу 96. Сколько раз он получит трехзначное число?',
      choices: ['3', '4', '5', '6', '7'],
      draw: drawNumberLine,
    },
    '2007/1': {
      question: 'Сколько общих букв у слов КЕНГУРУ и МАТЕМАТИКА?',
      choices: ['1', '2', '3', '4', '5'],
      draw: drawLetters,
    },
    '2008/6': {
      question: 'В первом аквариуме на 12 рыбок больше, чем во втором. Сколько рыбок надо переселить из первого аквариума во второй, чтобы рыбок в них стало поровну?',
      choices: ['12', '8', '6', '4', '2'],
      draw: drawAquariums,
    },
    '2009/2': {
      question: '200 × 9 + 200 + 9 = ?',
      choices: ['418', '1909', '2009', '4018', '20009'],
    },
    '2010/2': {
      question: 'Дети измерили шагами длину дорожки. У Ани получилось 17 шагов, у Наташи 15, у Дениса 14, у Вани 13 и у Тани 12. Кто из этих детей имеет самый длинный шаг?',
      choices: ['Аня', 'Наташа', 'Денис', 'Ваня', 'Таня'],
      draw: (step, frame) => drawBars(
        ['Аня', 'Наташа', 'Денис', 'Ваня', 'Таня'], [17, 15, 14, 13, 12], step === 2 ? 4 : -1, frame),
    },
    '2011/3': {
      question: 'Через три с половиной часа отправляется поезд, на котором Сёма поедет к бабушке. Боясь проспать, он проснулся полтора часа назад. За сколько часов до отправления поезда Сёма проснулся?',
      choices: ['за полтора часа', 'за 2 часа', 'за 3 с половиной часа', 'за 4 часа', 'за 5 часов'],
      draw: (step, frame) => drawTimeline(
        ['Пробуждение', 'Сейчас', 'Отправление'], [1.5, 3.5], ['1,5 ч', '3,5 ч'], step === 2 ? '5 часов' : '', frame),
    },
    '2012/4': {
      question: 'Три воздушных шарика стоят на 12 рублей больше, чем один шарик. Сколько стоит один шарик?',
      choices: ['4 руб.', '6 руб.', '8 руб.', '10 руб.', '12 руб.'],
      draw: drawBalloons,
    },
    '2013/4': {
      question: 'Миша измерил длины пяти палочек и записал результаты этих измерений. Какой из результатов А–Д самый большой?',
      choices: ['3 дм 2 см', '3 см 7 мм', '35 мм', '3 см', '302 мм'],
      draw: (step, frame) => step === 1
        ? drawEquations(equationsIn('300 + 20 = 320'), frame)
        : drawBars(['А', 'Б', 'В', 'Г', 'Д'], [320, 37, 35, 30, 302], 0, frame, ' мм'),
    },
    '2014/1': {
      question: 'Боря выложил из одинаковых палочек слово КЕНГУРУ. Сколько букв сложены из 5 палочек?',
      choices: ['2', '3', '4', '5', '6'],
      crop: [447, 4, 348, 81],
      illustration: 'Буквы слова КЕНГУРУ, сложенные из палочек',
      draw: drawStickLetters,
    },
    '2015/2': {
      question: 'Чему равна сумма двадцати сотен и пятнадцати?',
      choices: ['35', '215', '2015', '20015', '200015'],
    },
    '2016/2': {
      question: 'Крошке Ру 17 марта исполняется 7 недель и 3 дня. Когда ему исполнится 9 недель?',
      choices: ['21 марта', '24 марта', '26 марта', '28 марта', '30 марта'],
      draw: (step, frame) => drawTimeline(
        ['17 марта', step === 2 ? '21 марта' : '8 недель', step === 2 ? '28 марта' : '9 недель'],
        [4, 7], ['4 дня', '7 дней'], step === 2 ? '11 дней' : '', frame),
    },
    '2017/1': {
      question: 'Кенга составила пять примеров на сложение. Какая сумма самая большая?',
      choices: ['2 + 0 + 1 + 7', '2 + 0 + 17', '20 + 17', '20 + 1 + 7', '201 + 7'],
      draw: drawSums,
    },
    '2018/3': {
      question: 'В Петербурге 15 марта в 16 часов пошел снег, а 16 марта в 15 часов снегопад закончился. Сколько часов он продолжался?',
      choices: ['11', '12', '23', '24', '25'],
      draw: (step, frame) => drawTimeline(
        step === 1 ? ['15 марта, 16:00', 'Полночь'] : ['15 марта, 16:00', 'Полночь', '16 марта, 15:00'],
        step === 1 ? [8] : [8, 15], step === 1 ? ['8 ч'] : ['8 ч', '15 ч'], step === 2 ? '23 часа' : '', frame, 23),
    },
    '2019/1': {
      question: 'В зоопарке 21 ноября 2018 года родился кенгуренок. Сколько месяцев ему исполнилось 21 марта 2019 года?',
      choices: ['3', '4', '5', '6', '7'],
      draw: (step, frame) => drawTimeline(
        step === 1 ? ['21 нояб.', '21 дек.', '21 янв.'] : ['21 нояб.', '21 дек.', '21 янв.', '21 февр.', '21 марта'],
        step === 1 ? [1, 1] : [1, 1, 1, 1], step === 1 ? ['1 мес.', '1 мес.'] : ['1 мес.', '1 мес.', '1 мес.', '1 мес.'],
        step === 2 ? '4 месяца' : '', frame, 4),
    },
  };

  function drawSticks(step, frame) {
    let drawing = '';
    for (let i = 0; i < 6; i++) drawing += segment(101 + i * 70, 38, 101 + i * 70, 117, teal, 11);
    drawing += text(275, 150, '6 целых', 26);
    const gap = step === 1 ? 0 : 20 + 9 * progress(frame, 8);
    drawing += segment(567 - gap, 38, 567 - gap, 74, '#bc6340', 11);
    drawing += segment(567 + gap, 82, 567 + gap, 117, '#bc6340', 11);
    drawing += text(567, 150, step === 1 ? 'сломанная' : '2 половины', 26);
    return [180, drawing];
  }

  function drawPairs(step, frame) {
    let drawing = box(17, 22, 119, 61, mint) + text(77, 52, '2 + 2', 30);
    const active = Math.min(3, Math.floor(Math.max(0, frame) / 4));
    for (let i = 0; i < 4; i++) {
      const x = 151 + 139 * i;
      drawing += box(x, 22, 130, 61, step === 1 && i === active ? gold : muted);
      drawing += text(x + 65, 52, step === 1 ? '−2 + 2' : '0', 30);
      if (step === 1) drawing += segment(x + 65, 89, x + 65, 111, teal) + text(x + 65, 137, '0', 26, teal);
    }
    if (step === 2) drawing += text(360, 137, '2 + 2 = 4', 33, teal);
    return [173, drawing];
  }

  function drawHearts(step, frame, card) {
    if (step === 1) {
      let drawing = '';
      for (let i = 0; i < 4; i++) {
        const x = 105 + i * 128;
        drawing += box(x, 40, 105, 81, i === 3 ? muted : mint, line);
        drawing += text(x + 52, 80, i === 3 ? '◇' : '♥', 49, i === 3 ? ink : '#a34849');
      }
      return [175, drawing + text(360, 145, '3 из 4', 30, teal)];
    }
    const [url, w, h] = card;
    const choiceImage = globalThis.KENGURU_CHOICE_LAYOUTS?.['2003-3-4/3']?.options[3]?.image;
    const drawing = choiceImage
      ? `<image href="${escape(choiceImage)}" x="251" y="11" width="228" height="240"/>`
      : crop(url, w, h, [493, 66, 76, 80], 251, 11, 228, 240);
    const alpha = .45 + progress(frame, 9) * .55;
    return [260, drawing +
      `<g opacity="${alpha}">` +
      box(256, 15, 216, 158, 'none', '#a34849') + box(256, 176, 216, 73, 'none', teal) +
      text(490, 94, '9 сердец', 27, '#a34849', 'start') +
      text(490, 206, '3 другие фигуры', 23, teal, 'start') + '</g>'];
  }

  function drawStairs(step, frame) {
    let drawing = '';
    for (let i = 1; i <= 11; i++) {
      const x = 26 + 60 * (i - 1);
      const y = 176 - 13 * (i - 1);
      const landed = i % 2 === 0;
      const active = landed && i / 2 === Math.min(5, 1 + Math.floor(Math.max(frame, 0) / 4));
      const remaining = i === 11 && step === 2;
      drawing += box(x, y, 59, 36, active ? gold : remaining || landed ? mint : muted, line, 4);
      if (i < 11 || remaining) drawing += text(x + 30, y + 18, i, 24, landed || remaining ? teal : ink);
      if (landed) drawing += dot(x + 30, y - 15, active ? 8 : 5, teal);
      if (remaining) drawing += text(x + 30, y - 20, '+1', 22, teal);
    }
    return [225, drawing];
  }

  function drawKangaroos(step, frame, card) {
    const [url, w, h] = card;
    const locations = [[0, 0], [0, 1], [1, 0], [1, 3], [2, 2], [2, 3], [3, 2], [1, 2]];
    let drawing = '';
    for (let row = 0; row < 4; row++) {
      for (let col = 0; col < 4; col++) {
        const fill = step === 1 && (row === 1 || col === 2) ? gold
          : row === 3 && col === 1 ? mint : '#fff';
        drawing += box(204 + col * 64, 14 + row * 64, 64, 64, fill, line, 0);
      }
    }
    const moving = step === 2 ? (frame === 0 ? 1 : progress(frame, 10)) : 0;
    if (step === 2 && frame > 0) {
      drawing += `<path d="M364 110 Q230 144 300 238" fill="none" stroke="${teal}" stroke-width="3" stroke-dasharray="7 5"/>`;
    }
    locations.forEach(([row, col], i) => {
      const active = i === locations.length - 1;
      const shift = active ? moving : 0;
      const x = 210 + col * 64 - shift * 64;
      const y = 21 + row * 64 + shift * 128 - 37 * Math.sin(shift * Math.PI);
      if (active) drawing += box(x - 3, y - 3, 58, 57, mint, teal, 7);
      drawing += `<svg x="${x}" y="${y}" width="52" height="50" viewBox="549 19 49 46" style="overflow:hidden;mix-blend-mode:multiply">${image(url, w, h)}</svg>`;
    });
    const counts = moving === 1 ? [2, 2, 2, 2] : moving === 0 ? [2, 3, 2, 1] : [2, 2, 2, 1];
    for (let i = 0; i < 4; i++) {
      drawing += text(489, 46 + i * 64, counts[i], 24, teal);
      drawing += text(236 + i * 64, 296, i === 1 ? counts[3] : i === 2 ? counts[1] : 2, 24, teal);
    }
    return [321, drawing];
  }

  function drawNumberLine(step, frame) {
    let drawing = segment(44, 99, 676, 99, line, 4);
    for (let i = 0; i < 10; i++) {
      const x = 45 + i * 70;
      const marked = i === 4 || (step === 2 && i > 4);
      const active = i === 4 + Math.min(step === 1 ? 0 : 5, Math.floor(Math.max(0, frame) / 3));
      if (marked) drawing += box(x - 28, 53, 56, 44, active ? gold : mint);
      drawing += text(x, 75, 96 + i, 23, marked ? teal : ink) + dot(x, 99, marked ? 6 : 4, marked ? teal : line);
      if (marked) drawing += text(x, 126, '+' + i, 20, teal);
    }
    return [155, drawing];
  }

  function drawLetters(step, frame) {
    const words = ['КЕНГУРУ', 'МАТЕМАТИКА'];
    const active = Math.min(words[0].length - 1, Math.floor(Math.max(0, frame) / 3));
    return [166, words.map((word, row) => [...word].map((letter, i) => {
      const x = 360 - word.length * 32 + i * 64;
      const y = 19 + row * 67;
      const common = step === 2 && 'КЕ'.includes(letter);
      const comparable = step === 1 && (row === 0 ? i === active : letter === words[0][active]);
      return box(x, y, 56, 54, common ? mint : comparable ? gold : muted, common ? teal : line) +
        text(x + 28, y + 27, letter, 30, common ? teal : ink);
    }).join('')).join('')];
  }

  function drawAquariums(step, frame) {
    const moved = step === 1 ? 1 : 6;
    const now = frame === 0 ? moved : Math.min(moved, 1 + Math.floor(frame / 3));
    let drawing = '';
    for (let tank = 0; tank < 2; tank++) {
      const x = 21 + tank * 365;
      drawing += box(x, 18, 313, 128, mint, line);
      drawing += text(x + 156, 40, tank ? 'Второй аквариум' : 'Первый аквариум', 22);
      drawing += text(x + 40, 96, '□ +', 25, teal);
      for (let i = 0; i < (tank ? now : 12 - now); i++) {
        drawing += dot(x + 81 + (i % 6) * 36, 81 + Math.floor(i / 6) * 33, 11, tank ? '#bc6340' : teal);
      }
    }
    drawing += text(360, 82, '→', 27, ink);
    const difference = now === 6 ? '6 = 6' : `${12 - now} − ${now} = ${12 - 2 * now}`;
    drawing += text(360, 174, difference, 29, teal);
    return [197, drawing];
  }

  function drawBars(names, values, highlighted, frame, unit = '') {
    const max = Math.max(...values);
    const active = Math.min(values.length - 1, Math.floor(Math.max(0, frame) / 3));
    let drawing = '';
    for (let i = 0; i < values.length; i++) {
      const y = 12 + i * 46;
      const w = values[i] / max * 450;
      drawing += text(124, y + 17, names[i], 22, ink, 'end');
      drawing += box(146, y, w, 34, i === highlighted ? teal : i === active ? gold : muted, line, 7);
      drawing += text(156 + w, y + 17, values[i] + unit, 22, i === highlighted ? teal : ink, 'start');
    }
    return [values.length * 46 + 6, drawing];
  }

  function drawTimeline(labels, sizes, durations, total, frame, span = sizes.reduce((sum, size) => sum + size, 0)) {
    const active = Math.min(sizes.length - 1, Math.floor(Math.max(0, frame) / 6));
    let x = 103;
    let drawing = '';
    sizes.forEach((size, i) => {
      const end = x + 514 * size / span;
      drawing += segment(x, 65, end, 65, i === active ? '#c07848' : teal, 8);
      drawing += dot(x, 65, 8, teal);
      drawing += text(x, 100, labels[i], 21);
      drawing += text((x + end) / 2, 34, durations[i], 25, teal);
      x = end;
    });
    drawing += dot(x, 65, 8, teal) + text(x, 100, labels.at(-1), 21);
    if (total) drawing += box(103, 129, 514, 40, mint) + text(360, 149, total, 26, teal);
    return [total ? 183 : 128, drawing];
  }

  function drawBalloons(step, frame) {
    const active = Math.min(2, 1 + Math.floor(Math.max(0, frame) / 4));
    let drawing = segment(343, 62, 586, 62, teal, 3) + text(464, 36, '12 руб.', 26, teal);
    for (let i = 0; i < 3; i++) {
      const x = 175 + i * 144;
      const color = i === 0 ? '#a9b9b2' : i === active ? '#bc6340' : teal;
      drawing += dot(x, 118, 38, color);
      drawing += box(x - 6, 151, 12, 12, color, 'none', 0);
      drawing += segment(x, 162, x, 181, color);
      drawing += text(x, 207, i === 0 ? 'вычитаем' : step === 1 ? '?' : '6 руб.', 25, color);
      if (i === 0) drawing += segment(x - 45, 165, x + 45, 77, '#7d4940', 4);
    }
    return [239, drawing];
  }

  function drawStickLetters(step, frame, card) {
    const [url, w, h] = card;
    const sources = [[449, 42], [492, 48], [541, 53], [597, 49], [645, 46], [692, 52], [745, 48]];
    const values = [4, 5, 5, 3, 3, 5, 3];
    const active = Math.min(6, Math.floor(Math.max(0, frame) / 3));
    let drawing = '';
    for (let i = 0; i < sources.length; i++) {
      const [sx, sw] = sources[i];
      const x = 24 + i * 98;
      const relevant = step === 2 ? values[i] === 5 : values[i] !== 5;
      drawing += box(x, 21, 85, 126, relevant ? mint : muted, relevant ? teal : line);
      drawing += crop(url, w, h, [sx, 8, sw, 75], x + 14, 30, 56, 77);
      if (relevant) drawing += text(x + 43, 125, values[i], 24, active === i ? '#a24d36' : teal);
    }
    return [167, drawing];
  }

  function drawSums(step, frame) {
    if (step === 2) return drawBars(['А', 'Б', 'В', 'Г', 'Д'], [10, 19, 37, 28, 208], 4, frame);
    const expressions = authored['2017/1'].choices;
    const drawing = expressions.map((value, i) => {
      const x = 12 + i * 140;
      return box(x, 25, 135, 61, i === 4 ? mint : muted, i === 4 ? teal : line) +
        text(x + 67, 55, value, 22, i === 4 ? teal : ink);
    }).join('');
    return [113, drawing];
  }

  for (const [year, label, tasks] of globalThis.KENGURU_LEGACY ?? []) {
    const letters = year < 2008 ? latin : cyrillic;
    const lessons = [];
    const scenes = [];
    for (const [i, [width, height, , marks, key, name, explanation, note]] of tasks.entries()) {
      const number = i + 1;
      const answer = key === '?' ? null : latin.indexOf(key);
      const originalImage = `assets/years/${year}/task-${String(number).padStart(2, '0')}.webp`;
      const card = [originalImage, width, height];
      const authoredTask = authored[year + '/' + number];
      const imported = globalThis.KENGURU_LEGACY_CONDITIONS?.[year]?.[number];
      const native = authoredTask ?? imported;
      const illustration = !authoredTask && imported?.image
        ? svg(imported.imageWidth, imported.imageHeight, 'Рисунки и варианты из условия',
            `<image href="${escape(imported.image)}" width="${imported.imageWidth}" height="${imported.imageHeight}"/>`)
          .replace('<svg ', `<svg style="max-width:${imported.imageWidth}px" `)
        : '';
      const steps = [
        ['Твоё решение', 'Условие задачи', 'Выбери свой вариант ответа.'],
        ...explanation.map(([heading, message], stage) => [
          stage === explanation.length - 1 ? 'Ответ' : 'Шаг ' + (stage + 1), heading, message,
        ]),
      ];
      const formulas = explanation.map(([, message]) => equationsIn(message));
      const choice = answer === null ? '' : letters[answer];
      const description = `Условие и варианты задачи ${number} из оригинала.`;
      lessons.push({
        number,
        title: name,
        short: name,
        skill: '',
        answer,
        choices: native?.choices ?? ['', '', '', '', ''],
        choiceImages: native?.choiceImages,
        question: native?.question ?? '',
        conditionImage: !authoredTask ? imported?.image : undefined,
        questionNote: note,
        legacyOriginal: true,
        hideIntroText: Boolean(native),
        showCompletedStep: true,
        points: i < 10 ? 3 : i < 20 ? 4 : 5,
        originalImage,
        steps,
      });
      scenes.push((step, frame) => {
        if (step === 0 && authoredTask) {
          if (!authoredTask.crop) return '';
          const region = authoredTask.crop;
          const cropHeight = Math.round(720 * region[3] / Math.max(600, region[2]));
          const cropWidth = cropHeight * region[2] / region[3];
          return svg(720, cropHeight, authoredTask.illustration,
            crop(...card, region, (720 - cropWidth) / 2, 0, cropWidth, cropHeight));
        }
        if (step === 0 && native) return illustration;
        const final = step === steps.length - 1;
        const revealed = final ? choice : '';
        const answerLabel = revealed ? ` Ответ ${revealed}.` : '';
        if (step > 0) {
          const content = authoredTask?.draw
            ? authoredTask.draw(step, frame * 3, card)
            : formulas[step - 1].length ? drawEquations(formulas[step - 1], frame * 5) : null;
          if (content) return workedScene(content, steps[step][1] + '. ' + steps[step][2] + answerLabel, revealed);
          if (native) {
            if (!revealed) return '';
            return workedScene([0, ''], description + answerLabel, revealed);
          }
        }
        return renderOriginal(...card, description + answerLabel, final ? marks[answer] : null, frame);
      });
    }

    archive[year] = {
      year,
      id: year + '-3-4',
      grades: [3, 4],
      label,
      answerLetters: letters,
      sources: {
        tasksUrl: `${source}/kenguru_${year}_class_3-4.pdf`,
        answersUrl: `${source}/kenguru_${year}_answers.pdf`,
        solutionUrl: null,
      },
      lessons,
      scenes,
    };
  }
})();

